{"arguments":{"content":"import os
from pathlib import Path

DIR = Path(os.environ["PIPELINE_FLOW_DIR"])
dates = ["20190125", "20190126", "20190127", "20190128", "20190129"]

targets = [
    ("陕京二线", "石家庄站", "永清站"),
    ("冀宁线", "南京站", "南通站"),
]

sums = {t: 0.0 for t in targets}
detail = {t: [] for t in targets}

for d in dates:
    csv_path = DIR / f"{d}_pipeline.csv"
    with open(csv_path, encoding="utf-8") as f:
        header = f.readline()
        for line in f:
            parts = line.strip().split(",")
            if len(parts) < 5:
                continue
            start, end, typ, pipe, flow = parts[0], parts[1], parts[2], parts[3], parts[4]
            for t in targets:
                if pipe == t[0] and start == t[1] and end == t[2]:
                    v = abs(float(flow))
                    sums[t] += v
                    detail[t].append((d, v))

for t in targets:
    print(t, "days:", detail[t])
    print(t, "cumulative_abs_flow:", round(sums[t], 3))

a = sums[targets[0]]
b = sums[targets[1]]
print("diff (陕京二线 - 冀宁线):", round(a - b, 3))
