from pathlib import Path

DIR = Path(os.environ["PIPELINE_FLOW_DIR"])
dates = ["20190119", "20190120", "20190121"]
segments = [("石家庄站", "永清站"), ("精河站", "中卫站")]
lines = ["西气东输二线", "西气东输三线"]

totals = {}
details = {}
for d in dates:
    with open(DIR / f"{d}_pipeline.csv", encoding="utf-8") as f:
        header = f.readline()
        for line in f:
            parts = line.strip().split(",")
            if len(parts) < 5:
                continue
            start, end, typ, pipe, flow = parts[0], parts[1], parts[2], parts[3], float(parts[4])
            if pipe in lines and (start, end) in segments:
                key = (pipe, start, end)
                totals[pipe] = totals.get(pipe, 0.0) + abs(flow)
                details[key] = details.get(key, 0.0) + abs(flow)

for k in sorted(details):
    print(k, round(details[k], 3))
for p in lines:
    print("TOTAL", p, round(totals.get(p, 0.0), 3))
print("DIFF", round(totals.get(lines[0], 0.0) - totals.get(lines[1], 0.0), 3))
