{"arguments":{"content":"import csv
import os
from pathlib import Path

# The three daily node files to process
files = ['20191106_node.csv', '20191107_node.csv', '20191118_node.csv']

# Target stations
targets = ['靖边站', '南通站']

# Initialize accumulators (absolute flow sums per station across all files and pipelines)
abs_flows = {t: 0.0 for t in targets}

# Also track per-file breakdown
per_file = {t: {} for t in targets}

for fname in files:
    # Each file exists once in the NODE_FLOW_DIR env dir
    node_dir = Path(os.environ['NODE_FLOW_DIR'])
    csv_path = node_dir / fname
    with open(csv_path, 'r', encoding='utf-8') as f:
        reader = csv.DictReader(f)
        file_flows = {t: 0.0 for t in targets}
        for row in reader:
            station = row['站名'].strip()
            if station in targets:
                # "计算流量" (computed flow) column holds the signed flow value
                calc_flow_str = row.get('计算流量', '').strip()
                if calc_flow_str:
                    try:
                        flow_val = float(calc_flow_str)
                        abs_val = abs(flow_val)
                        abs_flows[station] += abs_val
                        file_flows[station] += abs_val
                    except ValueError:
                        print(f"Warning: could not parse flow for {station} in {fname}: '{calc_flow_str}'")
        for t in targets:
            per_file[t][fname] = file_flows[t]

# Print results
print("=== Per-file absolute flows (across all pipelines) ===")
for t in targets:
    for fname in files:
        print(f"  {t} - {fname}: {per_file[t][fname]:.3f}")

print("\n=== Cumulative absolute node flows (window 2019-11-06 to 2019-11-18) ===")
for t in targets:
    print(f"  {t}: {abs_flows[t]:.3f}")

print("\n=== Comparison ===")
jingbian = abs_flows['靖边站']
nantong = abs_flows['南通站']
if jingbian > nantong:
    print(f"  靖边站 吞吐更高: {jingbian:.3f} > {nantong:.3f} (差值 {jingbian - nantong:.3f})")
elif nantong > jingbian:
    print(f"  南通站 吞吐更高: {nantong:.3f} > {jingbian:.3f} (差值 {nantong - jingbian:.3f})")
else:
    print(f"  两站吞吐相等: {jingbian:.3f}")
","path":"temporary_dir/jingbian_nantong_aggregate.py"},"name":"write_file"}

{"arguments":{"content":"import os
from pathlib import Path
import csv

# Resolve data directory via env var (harness sets NODE_FLOW_DIR)
DIR = Path(os.environ["NODE_FLOW_DIR"])

dates = ["20191106", "20191107", "20191118"]
targets = {"靖边站", "南通站"}

# per-date, per-station absolute summed computed flow
per_date = {d: {s: 0.0 for s in targets} for d in dates}

for d in dates:
    csv_path = DIR / f"{d}_node.csv"
    with open(csv_path, newline="", encoding="utf-8") as f:
        reader = csv.DictReader(f)
        for row in reader:
            station = row["站名"]
            if station in targets:
                flow = row["计算流量"]
                if flow:
                    per_date[d][station] += abs(float(flow))

# Print per-date breakdown
for s in targets:
    print(f"\n{s}:")
    for d in dates:
        print(f"  {d}: {per_date[d][s]:.6f}")

# Identify peak day per station (highest absolute flow)
for s in targets:
    peak_day = max(dates, key=lambda d: per_date[d][s])
    print(f"\n{s} peak day: {peak_day} ({per_date[peak_day][s]:.6f})")

# Full aggregate (all 3 days)
print("\n=== Full aggregate (3 days) ===")
totals = {s: sum(per_date[d][s] for d in dates) for s in targets}
for s in targets:
    print(f"  {s}: {totals[s]:.6f}")
print(f"  靖边 > 南通? {totals['靖边站'] > totals['南通站']}")

# Aggregate excluding peak day (the window's highest day)
print("\n=== Excluding peak day (window highest) ===")
# Remove the single highest-flow day across the window for the ranking station
# The user asks: "if we remove the peak day in the window"
peak_overall = max(dates, key=lambda d: per_date[d]["靖边站"])
remaining = [d for d in dates if d != peak_overall]
totals_no_peak = {s: sum(per_date[d][s] for d in remaining) for s in targets}
for s in targets:
    print(f"  {s}: {totals_no_peak[s]:.6f}")
print(f"  靖边 > 南通? {totals_no_peak['靖边站'] > totals_no_peak['南通站']}")
print(f"  Reversal? {totals_no_peak['靖边站'] < totals_no_peak['南通站']}")
","path":"temporary_dir/verify_aggregate.py"},"name":"write_file"}

{"arguments":{"content":"import os, csv, sys
from pathlib import Path

node_dir = Path(os.environ["NODE_FLOW_DIR"])
dates = ["20191102", "20191103", "20191104", "20191105"]
targets = {"武汉站", "通州南站"}
accum = {t: 0.0 for t in targets}
daily = {t: [] for t in targets}

for d in dates:
    fp = node_dir / f"{d}_node.csv"
    if not fp.exists():
        print(f"MISSING: {fp}", file=sys.stderr)
        continue
    with open(fp, newline="", encoding="utf-8") as f:
        reader = csv.DictReader(f)
        for row in reader:
            station = row.get("站名", "").strip()
            if station in targets:
                val_str = row.get("计算流量", "").strip()
                if val_str:
                    val = abs(float(val_str))
                    accum[station] += val
                    daily[station].append((d, val))

for t in targets:
    print(f"\n=== {t} ===")
    for d, v in daily[t]:
        print(f"  {d}: {v:.3f}")
    print(f"  累计绝对节点流量: {accum[t]:.3f}")

wh, tz = accum["武汉站"], accum["通州南站"]
print(f"\n比较: 武汉站={wh:.3f}  vs  通州南站={tz:.3f}")
if wh > tz:
    diff = wh - tz
    print(f"武汉站吞吐更高，超出 {diff:.3f}，比 {(wh/tz if tz else float('inf')):.2f} 倍")
elif tz > wh:
    diff = tz - wh
    print(f"通州南站吞吐更高，超出 {diff:.3f}，比 {(tz/wh if wh else float('inf')):.2f} 倍")
else:
    print("两站吞吐相等")

# write report
reports_dir = Path(os.environ.get("OUTPUT_DIR", Path.cwd())) / "reports"
reports_dir.mkdir(parents=True, exist_ok=True)
report_path = reports_dir / "wh_tzn_aggregate_20191102_20191105.txt"
with open(report_path, "w", encoding="utf-8") as out:
    for t in targets:
        out.write(f"{t} 累计绝对节点流量: {accum[t]:.3f}\n")
    out.write(f"比较: 武汉站={wh:.3f} vs 通州南站={tz:.3f}\n")
print(f"\nReport written to: {report_path}")
","path":"temporary_dir/aggregate_nodes.py"},"name":"write_file"}
